async OnExecuteAsync(dto) {
        const { vmc, payload, data_model, search_options, data_model_id, total_count, current_template_info, prev_template_info, data_view_format, } = dto;
        if (data_model_id === undefined) {
            return;
        }
        const program_context = this.execution_context.getProgramContext();
        const dmc_map = program_context.data.dmc_map;
        const _data_view_format = data_view_format || dto.search_dmc?.getValueByPropId('data_view_format');
        if ((total_count ?? 0) >= 30 &&
            _data_view_format?.is_graph &&
            _.vIsEmpty(_data_view_format.setting?.comparatorColumn)) {
            const status = await vmc.confirmAsync($Resx.rex03618);
            if (!status) {
                vmc.setPageState("search" /* EN_CONST_ID.ISearchPageState */, (state) => {
                    state.display_search_panel = true;
                    state.display_search_button = false;
                });
                return;
            }
        }
        // #region : UI 필터 사용 여부 판단
        // 오천건 이상인지 판단
        const search_limit_count = search_options?.limit;
        const limit_count = program_context.sourceData.menu_attr?.page_size?.data.limit_count;
        // UI 필터 레이어 사용 여부
        const use_instant_layer = search_limit_count &&
            limit_count &&
            search_limit_count <= limit_count &&
            search_limit_count > (total_count ?? 0);
        // UI 필터 레이어 사용 불가능 한 경우 처리
        if (!use_instant_layer) {
            const instant_toolbar_data_model_id = 'instant_toolbar';
            delete dmc_map[instant_toolbar_data_model_id];
            const grid_request = this.execution_context.attr
                .createRequestBuilder()
                .setPAttrOwner("grid" /* EN_P_ATTR_DETAIL_OWNER.grid */)
                .build();
            const grid_attributes = this.execution_context.attr.mget(grid_request);
            if (grid_attributes.length > 0) {
                const instant_dragdrop_attr = grid_attributes?.find((x) => x.attr_id == 'instant_dragdrop');
                if (instant_dragdrop_attr && instant_dragdrop_attr.data) {
                    instant_dragdrop_attr.data.use = false;
                }
                const pre_instant_data_handler_attr = grid_attributes?.find((x) => x.attr_id == common_.template_attrs.output.pre_instant_data_handler);
                if (pre_instant_data_handler_attr) {
                    pre_instant_data_handler_attr.data = {};
                }
                const instant_data_handler_attr = grid_attributes?.find((x) => x.attr_id == common_.template_attrs.output.instant_data_handler);
                if (instant_data_handler_attr) {
                    instant_data_handler_attr.data = {};
                }
            }
        }
        // #endregion
        const grid_viewer_state = vmc.getViewerState({ data_model_id });
        let preserve_viewer_state;
        if (grid_viewer_state && !_data_view_format?.is_graph) {
            const preserve_program = common$1.ProgramBuilder.create("common$SetPreserveViewerStateProgram" /* EN_PROGRAM_ID.SetPreserveViewerStateProgram */, this.execution_context);
            ({ preserve_viewer_state } = await preserve_program.executeAsync({
                data_model_id,
                list_viewer_state: grid_viewer_state,
                template_unchange_tf: current_template_info?.sid == prev_template_info?.sid,
                search_type: payload.search_type,
            }));
            if (_.vIsEquals(payload.search_type, 'MORE')) {
                search_options.limit = payload.search_options.limit;
                //정렬 초기화
                delete search_options.sort;
                vmc.setPageRuntime("ISortInfoRuntime" /* EN_CONST_ID.ISortInfoRuntime */, undefined);
            }
        }
        if (!preserve_viewer_state) {
            preserve_viewer_state = {
                [data_model_id]: {},
            };
        }
        preserve_viewer_state[data_model_id]["instant_layer_sate" /* EN_CONST_ID.IGridViewerStateInstantLayer */] = { use: use_instant_layer };
        // dmc rebuild program (= updateDataAsync 대체 프로그램)
        const data_model_program = common$1.ProgramBuilder.create("common$DataModelRebuildProgram" /* EN_PROGRAM_ID.DataModelRebuildProgram */, this.execution_context);
        await data_model_program.executeAsync({
            dmc_id: data_model_id,
            xtemplate_info: dto.xtemplate_info,
            template_set_sid: current_template_info?.sid,
        });
    }

function createChartOption(platform_config, graphId = _.uniqueId('chart_')) {
    const _platform_config = platform_config || {};
    if (_platform_config.x1AxisList &&
        !_platform_config.x2AxisList &&
        _platform_config.y1AxisList &&
        !_platform_config.y2AxisList) {
        _platform_config.tooltipDataType = 'CATEGORY';
    }
    else {
        _platform_config.tooltipDataType = 'LEGEND_TEXT';
    }
    if (_platform_config.x1AxisList &&
        _platform_config.x2AxisList &&
        _platform_config.y1AxisList &&
        !_platform_config.y2AxisList) {
        _platform_config.trandelineDataType = 'GROUPS';
    }
    else {
        _platform_config.trandelineDataType = 'VALUES';
    }
    const chartOption = getChartOptionByMatrix({
        config: _platform_config,
        defaultConfig: ecount_browser_constant.ECChartDefaultConfig,
        graphId,
    });
    // 페이지 그래프 id 로 selector 변경
    chartOption.tooltipConfig.layoutSelector = `#${graphId}`;
    if (!_.isEmpty(graphId)) {
        chartOption.layoutSelector = `#${graphId}_ecChartLayout`;
        if (chartOption.legendConfig) {
            chartOption.legendConfig.layoutSelector = `#${graphId}_ecChartLegend`;
        }
    }
    getChartOptionFilter({ chartOption, platform_config: _platform_config });
    setChartOption({ chartOption, platform_config: _platform_config });
    delete chartOption.legendConfig?.events;
    delete chartOption.tooltipConfig?.events;
    return chartOption;
}

function getChartOptionByMatrix({ config, defaultConfig, graphId, }) {
    const hasX2AxisData = !!(config.x2ColId && config.x2AxisList);
    const hasY2AxisData = !!(config.y2ColId && config.y2AxisList);
    const legendColors = _.cloneDeep(config.legendColors || defaultConfig.colors);
    const categoryColors = config.categoryColors || undefined;
    const result = {
        graphId,
        legendColors: legendColors,
        categoryColors: categoryColors,
        seriesColors: legendColors,
        tooltipConfig: {},
        datas: [],
        legendConfig: {
            shapeDatas: [],
            textDatas: [],
        },
    };
    //1*1
    if (!hasX2AxisData && !hasY2AxisData) {
        return _.extend(result, ecount?.graph?.data?.getOnoByOneOptionOfECChart(config));
    }
    //1*2
    if (!hasX2AxisData && hasY2AxisData) {
        return _.extend(result, ecount?.graph?.data?.getOnoByTwoOptionOfECChart(config));
    }
    //2*1
    if (hasX2AxisData && !hasY2AxisData) {
        return _.extend(result, ecount?.graph?.data?.getTwoByOneOptionOfECChart(config));
    }
    //2*2
    if (hasX2AxisData && hasY2AxisData) {
        return _.extend(result, ecount?.graph?.data?.getTwoByTwoOptionOfECChart(config));
    }
    return result;
}

function getChartOptionFilter({ chartOption, platform_config, }) {
    const _platform_config_config = platform_config || {};
    const _filterData = platform_config.filterData;
    /**
     * 1. data filter
     * 2. change data color
     */
    if (!_.isEmpty(_filterData)) {
        switch (_platform_config_config.graphType) {
            case 'pie':
                {
                    //category 제외
                    const datas = [];
                    _filterData?.checkedList.forEach(function (checkedData) {
                        const checkedDataLastIndex = checkedData.lastIndexOf(ecount?.grid?.constValue?.rowKeySeparator);
                        if (checkedDataLastIndex > -1) {
                            const category = checkedData.substring(checkedDataLastIndex + 1);
                            const categoryDataIndex = chartOption.datas.findIndex(function (data) {
                                return category == data.category;
                            });
                            categoryDataIndex > -1 && datas.push(chartOption.datas.splice(categoryDataIndex, 1)[0]);
                        }
                    });
                    chartOption.datas = datas;
                    //legend 제외 - groupId
                    _filterData?.legendData.forEach(function (legendData) {
                        if (!legendData.CHECKED) {
                            const categoryDataIndex = chartOption.datas.findIndex(function (categoryData) {
                                return categoryData.category == legendData.GROUPID;
                            });
                            categoryDataIndex > -1 && chartOption.datas.splice(categoryDataIndex, 1);
                            const shapeDataIndex = chartOption.legendConfig.shapeDatas.findIndex(function (shapeData) {
                                return legendData.GROUPID == shapeData.groupId;
                            });
                            shapeDataIndex > -1 && chartOption.legendConfig.shapeDatas.splice(shapeDataIndex, 1);
                            const textDataIndex = chartOption.legendConfig.textDatas.findIndex(function (textData) {
                                return legendData.GROUPID == textData.groupId;
                            });
                            textDataIndex > -1 && chartOption.legendConfig.textDatas.splice(textDataIndex, 1);
                        }
                    });
                    //legend 색상 변경 - groupId
                    _filterData?.legendData.forEach(function (legendData) {
                        if (legendData.CHECKED && legendData.COLOR) {
                            const shapeDataIndex = chartOption.legendConfig.shapeDatas.findIndex(function (shapeData) {
                                return legendData.GROUPID == shapeData.groupId;
                            });
                            if (shapeDataIndex > -1) {
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].strokeColor = legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].fillColor = legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].shapeBackgroundColor =
                                    legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].shapePositiveBackgroundColor =
                                    legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].shapeNegativeBackgroundColor =
                                    legendData.COLOR;
                            }
                            chartOption.datas.forEach(function (categoryData) {
                                if (categoryData.category == legendData.GROUPID) {
                                    categoryData.values.forEach(function (groupData) {
                                        groupData.strokeColor = legendData.COLOR;
                                        groupData.fillColor = legendData.COLOR;
                                        groupData.shapeBackgroundColor = legendData.COLOR;
                                        groupData.shapePositiveBackgroundColor = legendData.COLOR;
                                        groupData.shapeNegativeBackgroundColor = legendData.COLOR;
                                    });
                                }
                            });
                        }
                    });
                }
                break;
            default:
                {
                    //category 제외
                    _filterData?.categoryData.forEach(function (categoryData) {
                        if (!categoryData.CHECKED) {
                            const categoryDataIndex = chartOption.datas.findIndex(function (data) {
                                return data.category == categoryData.SUB_GUBUN;
                            });
                            categoryDataIndex > -1 && chartOption.datas.splice(categoryDataIndex, 1);
                        }
                    });
                    //legend 제외 - groupId
                    _filterData?.legendData.forEach(function (legendData) {
                        if (!legendData.CHECKED) {
                            chartOption.datas.forEach(function (categoryData) {
                                const groupDataIndex = categoryData.values.findIndex(function (groupData) {
                                    return legendData.GROUPID == groupData.groupId;
                                });
                                groupDataIndex > -1 && categoryData.values.splice(groupDataIndex, 1);
                            });
                            const shapeDataIndex = chartOption.legendConfig.shapeDatas.findIndex(function (shapeData) {
                                return legendData.GROUPID == shapeData.groupId;
                            });
                            shapeDataIndex > -1 && chartOption.legendConfig.shapeDatas.splice(shapeDataIndex, 1);
                            const textDataIndex = chartOption.legendConfig.textDatas.findIndex(function (textData) {
                                return legendData.GROUPID == textData.groupId;
                            });
                            textDataIndex > -1 && chartOption.legendConfig.textDatas.splice(textDataIndex, 1);
                        }
                    });
                    //legend 색상 변경 - groupId
                    _filterData?.legendData.forEach(function (legendData) {
                        if (legendData.CHECKED && legendData.COLOR) {
                            const shapeDataIndex = chartOption.legendConfig.shapeDatas.findIndex(function (shapeData) {
                                return legendData.GROUPID == shapeData.groupId;
                            });
                            if (shapeDataIndex > -1) {
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].strokeColor = legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].fillColor = legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].shapeBackgroundColor =
                                    legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].shapePositiveBackgroundColor =
                                    legendData.COLOR;
                                chartOption.legendConfig.shapeDatas[shapeDataIndex].shapeNegativeBackgroundColor =
                                    legendData.COLOR;
                            }
                            chartOption.datas.forEach(function (categoryData) {
                                const groupDataIndex = categoryData.values.findIndex(function (groupData) {
                                    return legendData.GROUPID == groupData.groupId;
                                });
                                if (groupDataIndex > -1) {
                                    categoryData.values[groupDataIndex].strokeColor = legendData.COLOR;
                                    categoryData.values[groupDataIndex].fillColor = legendData.COLOR;
                                    categoryData.values[groupDataIndex].shapeBackgroundColor = legendData.COLOR;
                                    categoryData.values[groupDataIndex].shapePositiveBackgroundColor = legendData.COLOR;
                                    categoryData.values[groupDataIndex].shapeNegativeBackgroundColor = legendData.COLOR;
                                }
                            });
                        }
                    });
                    //category 색상 변경
                    _filterData?.categoryData.forEach(function (categoryData) {
                        if (categoryData.CHECKED && categoryData.COLOR) {
                            const categoryDataIndex = chartOption.datas.findIndex(function (data) {
                                return data.category == categoryData.SUB_GUBUN;
                            });
                            if (categoryDataIndex > -1) {
                                chartOption.datas[categoryDataIndex].values.forEach(function (groupData) {
                                    groupData.strokeColor = categoryData.COLOR;
                                    groupData.fillColor = categoryData.COLOR;
                                    groupData.shapeBackgroundColor = categoryData.COLOR;
                                    groupData.shapePositiveBackgroundColor = categoryData.COLOR;
                                    groupData.shapeNegativeBackgroundColor = categoryData.COLOR;
                                });
                            }
                        }
                    });
                }
                break;
        }
    }
}

composePlatformConfig(axis_config) {
        const platform_config = _.extend({}, this.graph_widget_config, axis_config);
        // 비교대상 설정 - 상위 10개만, 하위 10개만
        if (platform_config?.isShowHighest || platform_config?.isShowLowest) {
            // pie 차트는 y1ColumnId 설정
            if (platform_config.graphType === "pie" /* EN_GRAPH_TYPE.pie */) {
                platform_config['comparatorPropName'] = platform_config?.y1ColumnId;
            }
            else {
                platform_config['comparatorPropName'] = platform_config?.comparatorColumn;
            }
            // 집계 comparatorPropName 설정
            if (this.is_aggregate) {
                platform_config['comparatorPropName'] = platform_config?.y1ColumnId;
            }
        }
        return platform_config;
    }

async (request) => {
        const { vmc, owner, execution_context } = request;
        const program_context = execution_context.getProgramContext();
        // 페이지 기본 정보
        const search_attribute = program_context.sourceData.menu_attr?.search?.data;
        const search_data_model_id = search_attribute?.data_model_id.search;
        const search_dmc = program_context.data.dmc_map[search_data_model_id];
        // v3_menu_info
        const v3_menu_info = program_context.sourceData.menu?.v3_menu_info;
        const prg_id = v3_menu_info?.status?.prg_id;
        const template_data_model_id = search_attribute?.data_model_id.template;
        const template_dmc = program_context.data.dmc_map[template_data_model_id];
        //집계
        const aggregate_prop_id = search_dmc.getPropIdByReferType('aggregate');
        const template_infos = program_context.sourceData.menu_attr?.template_info?.data;
        const aggregate_key = search_dmc.getValueByPropId(aggregate_prop_id)?.aggregate_key?.key ??
            _.vFirst(Object.keys(_.vSafe(template_infos, {})));
        //유저가 조회중인 현재 양식의 sid
        const current_template_info = template_dmc.getValueByPropId('applied_template');
        const template = template_infos[aggregate_key].template_list.find((x) => x.sid === current_template_info);
        const is_za_template = template?.is_za_template;
        const screen_type = _.vSafe(template?.screen_type, "print" /* EN_SCREEN_TYPE.Print */);
        //양식 정보 (X,Y축 검색조건 불러오기)
        let form = request.vmc.getPageRuntime('formDesignData');
        request.vmc.setPageRuntime('prev_template_info', current_template_info);
        const prop_list_program = await common.ProgramBuilder.create("common$GetGraphColumnInfoProgram" /* EN_PROGRAM_ID.GetGraphColumnInfoProgram */, request.execution_context);
        form = await prop_list_program.executeAsync({
            // dm_manager: request.dm_manager,
            vmc: request.vmc,
            current_template_info: current_template_info,
            is_za_template,
            screen_type,
        });
        if (_.vIsEmpty(form)) {
            return;
        }
        request.vmc.setPageRuntime('formDesignData', form);
        //5.0 화면 그릴 때 사용하는 pageRuntime을 null로 치환한다.
        request.vmc.setPageRuntime("IGraphOption" /* EN_CONST_ID.IGraphOption */, null);
        //------------------------------------------------------
        // 양식데이터로 validate 체크 (그래프보기 제한되는 경우)
        //------------------------------------------------------
        const validator = await common.ProgramBuilder.create("common$GraphSettingValidatorAttrProgram" /* EN_PROGRAM_ID.GraphSettingValidatorAttrProgram */, request.execution_context);
        const is_valid = await validator.executeAsync({
            vmc: request.vmc,
            // dm_manager: request.dm_manager,
            current_template_info: current_template_info,
            is_za_template: is_za_template,
            screen_type,
            template_sub_type: template_infos[aggregate_key].template_sub_type,
            menu_type: program_context.data.menu_type,
            axis_info: form.axis_info,
        });
        if (is_valid === false) {
            await request.vmc.alertAsync($Resx.rex10265);
            return;
        }
        //------------------------------------------------------
        // 그래프 보기 설정 팝업 호출
        //------------------------------------------------------
        const pageOption = {
            axisInfo: form.axis_info,
            graphSetting: template_dmc.getValueByPropId('data_view_format')?.setting,
        };
        const feature = request.execution_context.getFeature("IHandleRouteFeature$V56" /* EN_FEATURE_ID.IHandleRouteFeature */);
        const popup_result = await feature.openPopupAsync({
            identifier: "IConfigureGraphOptionsPage" /* EN_PAGE_ID.IConfigureGraphOptionsPage */,
            bizz_sid: program_context.data.bizz_sid,
            param: {
                from_program_id: prg_id,
                pageOption: pageOption,
            },
        }, {});
        // TODO GRAPH: 팝업 결과로 받아오는 그래프 설정 정보의 xAxis, yAxis 정보가 반대로 내려옴
        // 소비처(ChartWidgetAstInterceptor)는 이와 무관하게 처리되어서 동작은 하나 추후 해당 팝업을 다른 소비처에서 호출시 문제 여지 있음
        //------------------------------------------------------
        // 그래프 설정 팝업창 동작 후 처리
        //------------------------------------------------------
        if (popup_result.message) {
            popup_result.message.callback && popup_result.message.callback();
            //TODO:SetPageRuntime or setValueByPropId 중 하나로 통일시켜야 함.
            request.vmc.setPageRuntime("IGraphOption" /* EN_CONST_ID.IGraphOption */, popup_result.message.graphSetting);
            request.vmc.setPageRuntime('isAppliedGraphOption', true);
            if (popup_result.message.graphSetting?.graphTitle == undefined) {
                const { bizz_type, menu_type } = program_context.data;
                const header_data_model_id = common_$1.getHeaderModelId(bizz_type, menu_type);
                const header_dmc = program_context.data.dmc_map[header_data_model_id];
                const menu_display_attr = header_dmc
                    .getAttrs()
                    ?.filter((x) => x.prop_id == 'menu_name' && x.attr_id == 'display_name');
                popup_result.message.graphSetting.graphTitle = menu_display_attr[0].data;
            }
            template_dmc?.setValueByPropId('data_view_format', {
                setting: popup_result.message.graphSetting,
                is_graph: true,
            });
        }
        return;
    }

async (request) => {
        const { vmc, owner, execution_context } = request;
        const program_context = execution_context.getProgramContext();
        const search_attribute = program_context.sourceData.menu_attr?.search?.data;
        const template_data_model_id = search_attribute?.data_model_id.template;
        const template_dmc = program_context.data.dmc_map[template_data_model_id];
        const data_view_format = template_dmc.getValueByPropId('data_view_format');
        const setting = data_view_format?.setting;
        if (!setting)
            return;
        const data_model_id = common_.CurrentUtil.getModelInfo(execution_context, "status" /* EN_MODEL_REFER_TYPE.Status */)
            ?.model_id;
        const { graph_config, platform_config, origin_graph_config } = vmc.getViewerStateWritable({
            data_model_id,
        });
        const originDatas = origin_graph_config.datas;
        const origin_legend_data = { legendData: origin_graph_config.legendConfig.textDatas };
        const { legendData, categoryData, useYn } = getFilterData(_.extend({}, platform_config, graph_config), setting, originDatas, origin_legend_data);
        //------------------------------------------------------
        // 필터설정 팝업 호출
        //------------------------------------------------------
        const feature = execution_context.getFeature("IHandleRouteFeature$V56" /* EN_FEATURE_ID.IHandleRouteFeature */);
        const popup_result = await feature.openPopupAsync({
            identifier: "IConfigureGraphFilterPage" /* EN_PAGE_ID.IConfigureGraphFilterPage */,
            bizz_sid: program_context.data.bizz_sid,
            param: {
                legendData,
                categoryData,
                checkedList: graph_config.checkedList,
                useYn: useYn,
            },
        }, {});
        //------------------------------------------------------
        // 필터설정 팝업창 동작 후 처리
        //------------------------------------------------------
        if (popup_result.message) {
            const { checkedList, categoryData, legendData } = popup_result.message;
            graph_config.filterData = popup_result.message;
            const filter_graph_config = createChartOption(_.extend({}, platform_config, { filterData: popup_result.message }), graph_config.graphId);
            filter_graph_config.checkedList = checkedList;
            vmc.setViewerState({ data_model_id }, (viewer_state) => {
                return {
                    ...viewer_state,
                    graph_config: _.extend(filter_graph_config, {
                        checkedList: checkedList,
                        categoryColors: _.map(categoryData, (data) => data.COLOR),
                        legendColors: _.map(legendData, (data) => data.COLOR),
                    }),
                    is_reset_size: true,
                };
            });
            popup_result.message.callback && popup_result.message.callback();
        }
        return;
    }

