(graphConfig, graphSetting, datas, origin_legend_data) => {
    const legendData = [], categoryData = [], configColor = _.cloneDeep(graphConfig.seriesColors);
    let useYn;
    if (graphSetting?.graphType == 'bar' || graphSetting?.graphType == 'horizontalBar') {
        useYn = true;
    }
    //범주 색지정
    if (!graphConfig.categoryColors) {
        graphConfig.categoryColors = [];
    }
    const vCategoryData = datas[0];
    //범례 색지정
    if (graphConfig.legendColors) {
        vCategoryData.values.forEach(function (data, i) {
            if (!graphConfig.legendColors[i]) {
                graphConfig.legendColors[i] = configColor[i % configColor.length];
            }
        });
    }
    else {
        graphConfig.legendColors = [];
    }
    switch (graphSetting?.graphType) {
        case 'pie': {
            //범례
            const categoryCount = datas.length;
            datas.forEach(function (categoryData, categoryDataIndex) {
                if (categoryDataIndex == 0) {
                    legendData.push({
                        MAIN_GUBUN: $Resx.rex02523 || 'RES::범례',
                        SUB_GUBUN: categoryData.category,
                        COLOR: graphConfig.legendColors[categoryDataIndex],
                        ID: categoryDataIndex,
                        GROUPID: categoryData.category,
                        ROW_CNT: categoryCount,
                        DATA_TYPE: 2,
                    });
                }
                else {
                    legendData.push({
                        MAIN_GUBUN: $Resx.rex02523 || 'RES::범례',
                        SUB_GUBUN: categoryData.category,
                        COLOR: graphConfig.legendColors[categoryDataIndex],
                        ID: categoryDataIndex,
                        GROUPID: categoryData.category,
                        DATA_TYPE: 2,
                    });
                }
            });
            break;
        }
        default:
            //범주
            for (let i = 0, len = datas.length; i < len; i++) {
                if (i == 0) {
                    categoryData.push({
                        MAIN_GUBUN: $Resx.rex02524 || 'RES::범주',
                        SUB_GUBUN: datas[i].category,
                        COLOR: graphConfig.categoryColors[i],
                        ROW_CNT: len,
                        DATA_TYPE: 1,
                    });
                }
                else {
                    categoryData.push({
                        MAIN_GUBUN: $Resx.rex02524 || 'RES::범주',
                        SUB_GUBUN: datas[i].category,
                        COLOR: graphConfig.categoryColors[i],
                        DATA_TYPE: 1,
                    });
                }
            }
            //2 * 1 matrix
            if (graphConfig.x1AxisList && graphConfig.x2AxisList && !graphConfig.y2AxisList) {
                //범례
                for (let i = 0, len = vCategoryData.values.length; i < len; i++) {
                    if (i == 0) {
                        legendData.push({
                            MAIN_GUBUN: $Resx.rex02523 || 'RES::범례',
                            SUB_GUBUN: vCategoryData.values[i].groupId,
                            COLOR: graphConfig.legendColors[i],
                            ID: i,
                            GROUPID: vCategoryData.values[i].groupId,
                            ROW_CNT: len,
                            DATA_TYPE: 2,
                        });
                    }
                    else {
                        legendData.push({
                            MAIN_GUBUN: $Resx.rex02523 || 'RES::범례',
                            SUB_GUBUN: vCategoryData.values[i].groupId,
                            COLOR: graphConfig.legendColors[i],
                            ID: i,
                            GROUPID: vCategoryData.values[i].groupId,
                            DATA_TYPE: 2,
                        });
                    }
                }
            }
            else {
                /*
                1 * n matrix
                2 * 2 matrix
                */
                //범례
                for (let i = 0, len = vCategoryData.values.length; i < len; i++) {
                    const legendTextData = origin_legend_data.legendData.find((data) => data.groupId == vCategoryData.values[i].groupId);
                    if (i == 0) {
                        legendData.push({
                            MAIN_GUBUN: $Resx.rex02523 || 'RES::범례',
                            SUB_GUBUN: (legendTextData && legendTextData.value) || '',
                            COLOR: graphConfig.legendColors[i],
                            ID: i,
                            GROUPID: vCategoryData.values[i].groupId,
                            ROW_CNT: len,
                            DATA_TYPE: 2,
                        });
                    }
                    else {
                        legendData.push({
                            MAIN_GUBUN: $Resx.rex02523 || 'RES::범례',
                            SUB_GUBUN: (legendTextData && legendTextData.value) || '',
                            COLOR: graphConfig.legendColors[i],
                            ID: i,
                            GROUPID: vCategoryData.values[i].groupId,
                            DATA_TYPE: 2,
                        });
                    }
                }
            }
            break;
    }
    return {
        legendData: legendData,
        categoryData: categoryData,
        useYn: useYn,
    };
}
